<?php
session_start();
require_once 'config.php';
require_once 'content_repository.php';
if (($_SESSION['auth_user']['role'] ?? '') !== 'admin') { header('Location: auth.php'); exit; }
ensureContentSchema($conn);

function backToContentAdmin(): void { header('Location: content_admin.php?saved=1'); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    requireContentCsrf();
    $action = $_POST['action'] ?? '';
    if ($action === 'feedback_status') {
        $id=(int)($_POST['id']??0); $status=$_POST['status']??'pending';
        if (in_array($status,['pending','approved','rejected'],true)) { $s=$conn->prepare('UPDATE feedback SET status=? WHERE id=?'); $s->bind_param('si',$status,$id); $s->execute(); }
    } elseif ($action === 'faq_save') {
        $id=(int)($_POST['id']??0); $q=trim($_POST['question']??''); $a=trim($_POST['answer']??''); $o=(int)($_POST['sort_order']??0); $active=isset($_POST['is_active'])?1:0;
        if ($q!=='' && $a!=='') { if($id){$s=$conn->prepare('UPDATE faqs SET question=?,answer=?,sort_order=?,is_active=? WHERE id=?');$s->bind_param('ssiii',$q,$a,$o,$active,$id);}else{$s=$conn->prepare('INSERT INTO faqs(question,answer,sort_order,is_active) VALUES(?,?,?,?)');$s->bind_param('ssii',$q,$a,$o,$active);} $s->execute(); }
    } elseif ($action === 'faq_delete') { $id=(int)($_POST['id']??0); $s=$conn->prepare('DELETE FROM faqs WHERE id=?');$s->bind_param('i',$id);$s->execute();
    } elseif ($action === 'post_save') {
        $id=(int)($_POST['id']??0); $title=trim($_POST['title']??''); $slug=contentSlug($_POST['slug']?:$title); $excerpt=trim($_POST['excerpt']??''); $body=trim($_POST['content']??''); $image=trim($_POST['cover_image']??''); $category=trim($_POST['category']??''); $status=$_POST['status']==='published'?'published':'draft'; $published=$status==='published'?date('Y-m-d H:i:s'):null;
        if($title!==''){ if($id){$s=$conn->prepare('UPDATE blog_posts SET slug=?,title=?,excerpt=?,content=?,cover_image=?,category=?,status=?,published_at=COALESCE(published_at,?) WHERE id=?');$s->bind_param('ssssssssi',$slug,$title,$excerpt,$body,$image,$category,$status,$published,$id);}else{$s=$conn->prepare('INSERT INTO blog_posts(slug,title,excerpt,content,cover_image,category,status,published_at) VALUES(?,?,?,?,?,?,?,?)');$s->bind_param('ssssssss',$slug,$title,$excerpt,$body,$image,$category,$status,$published);} $s->execute(); }
    } elseif ($action === 'post_delete') { $id=(int)($_POST['id']??0);$s=$conn->prepare('DELETE FROM blog_posts WHERE id=?');$s->bind_param('i',$id);$s->execute();
    } elseif ($action === 'profile_save') {
        $uid=(int)($_POST['user_id']??0); $slug=contentSlug($_POST['slug']??''); $intro=trim($_POST['introduction']??'');$edu=trim($_POST['education']??'');$exp=trim($_POST['experience_text']??'');$cases=trim($_POST['case_count']??'');$note=trim($_POST['consultation_note']??'');$photo=trim($_POST['photo']??'');$pub=isset($_POST['is_published'])?1:0; $caseVal=$cases===''?null:(int)$cases;
        if($uid && $slug!==''){$s=$conn->prepare('INSERT INTO doctor_profiles(user_id,slug,introduction,education,experience_text,case_count,consultation_note,photo,is_published) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE slug=VALUES(slug),introduction=VALUES(introduction),education=VALUES(education),experience_text=VALUES(experience_text),case_count=VALUES(case_count),consultation_note=VALUES(consultation_note),photo=VALUES(photo),is_published=VALUES(is_published)');$s->bind_param('issssissi',$uid,$slug,$intro,$edu,$exp,$caseVal,$note,$photo,$pub);$s->execute();}
    } elseif ($action === 'term_save') {
        $id=(int)($_POST['id']??0);$pid=(int)($_POST['product_id']??0);$name=trim($_POST['service_name']??'');$priceNote=trim($_POST['price_note']??'');$warranty=trim($_POST['warranty_text']??'');$payment=trim($_POST['payment_note']??'');$order=(int)($_POST['sort_order']??0);$active=isset($_POST['is_active'])?1:0;
        if($name!==''){if($id){$s=$conn->prepare('UPDATE service_terms SET product_id=NULLIF(?,0),service_name=?,price_note=?,warranty_text=?,payment_note=?,sort_order=?,is_active=? WHERE id=?');$s->bind_param('issssiii',$pid,$name,$priceNote,$warranty,$payment,$order,$active,$id);}else{$s=$conn->prepare('INSERT INTO service_terms(product_id,service_name,price_note,warranty_text,payment_note,sort_order,is_active) VALUES(NULLIF(?,0),?,?,?,?,?,?)');$s->bind_param('issssii',$pid,$name,$priceNote,$warranty,$payment,$order,$active);} $s->execute();}
    } elseif ($action === 'term_delete') {$id=(int)($_POST['id']??0);$s=$conn->prepare('DELETE FROM service_terms WHERE id=?');$s->bind_param('i',$id);$s->execute();
    } elseif ($action === 'trust_save') {
        $id=(int)($_POST['id']??0);$type=in_array($_POST['item_type']??'', ['license','certificate','partner'],true)?$_POST['item_type']:'certificate';$title=trim($_POST['title']??'');$issuer=trim($_POST['issuer']??'');$code=trim($_POST['credential_code']??'');$url=trim($_POST['evidence_url']??'');$image=trim($_POST['image']??'');$desc=trim($_POST['description']??'');$verified=isset($_POST['is_verified'])?1:0;$public=isset($_POST['is_public'])?1:0;
        if($title!==''){if($id){$s=$conn->prepare('UPDATE trust_items SET item_type=?,title=?,issuer=?,credential_code=?,evidence_url=?,image=?,description=?,is_verified=?,is_public=? WHERE id=?');$s->bind_param('sssssssiii',$type,$title,$issuer,$code,$url,$image,$desc,$verified,$public,$id);}else{$s=$conn->prepare('INSERT INTO trust_items(item_type,title,issuer,credential_code,evidence_url,image,description,is_verified,is_public) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('sssssssii',$type,$title,$issuer,$code,$url,$image,$desc,$verified,$public);} $s->execute();}
    } elseif ($action === 'trust_delete') {$id=(int)($_POST['id']??0);$s=$conn->prepare('DELETE FROM trust_items WHERE id=?');$s->bind_param('i',$id);$s->execute();
    } elseif ($action === 'setting_save') {$key=$_POST['setting_key']??'';$value=trim($_POST['setting_value']??'');if($key==='google_reviews_embed_url'){$s=$conn->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->bind_param('ss',$key,$value);$s->execute();}}
    backToContentAdmin();
}
$token=contentCsrfToken();
$feedback=contentRows($conn,"SELECT * FROM feedback ORDER BY id DESC LIMIT 30");
$faqs=contentRows($conn,"SELECT * FROM faqs ORDER BY sort_order,id");
$posts=contentRows($conn,"SELECT * FROM blog_posts ORDER BY updated_at DESC");
$doctors=contentRows($conn,"SELECT u.id,u.full_name,u.specialty,p.slug,p.introduction,p.education,p.experience_text,p.case_count,p.consultation_note,p.photo,p.is_published FROM users u LEFT JOIN doctor_profiles p ON p.user_id=u.id WHERE u.role='doctor' ORDER BY u.id");
$products=contentRows($conn,"SELECT id,name,price FROM products WHERE COALESCE(is_active,1)=1 ORDER BY name"); $terms=contentRows($conn,"SELECT * FROM service_terms ORDER BY sort_order,id"); $trust=contentRows($conn,"SELECT * FROM trust_items ORDER BY item_type,sort_order,id");
?>
