<details><summary>Bảng giá, bảo hành & thanh toán</summary><form method="post"><input type="hidden" name="csrf" value="<?=$token?>"><input type="hidden" name="action" value="term_save"><div class="row"><select name="product_id"><option value="0">Không liên kết dịch vụ</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select><input name="service_name" placeholder="Tên mục hiển thị" required></div><input name="price_note" placeholder="Ghi chú giá (vd: giá tham khảo, xác nhận sau thăm khám)"><textarea name="warranty_text" placeholder="Chính sách bảo hành đã xác thực"></textarea><textarea name="payment_note" placeholder="Thanh toán/trả góp đã xác thực"></textarea><label><input type="checkbox" name="is_active" checked> Hiển thị</label><button>Lưu chính sách</button></form><?php foreach($terms as $t):?><div class="list"><b><?=htmlspecialchars($t['service_name'])?></b><p><?=htmlspecialchars($t['warranty_text']??'Chưa khai báo')?></p><form method="post"><input type="hidden" name="csrf" value="<?=$token?>"><input type="hidden" name="action" value="term_delete"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="danger">Xóa</button></form></div><?php endforeach;?></details>
